def dup_groups(cs, sym=False):
    byp=defaultdict(list)
    for x in cs: byp[x['pat']].append(x)
    if not sym: return {p:v for p,v in byp.items() if len(v)>1}
    # merge groups connected by symmetry
    pats=list(byp); parent={p:p for p in pats}
    def find(a):
        while parent[a]!=a: a=parent[a]
        return a
    for a in pats:
        for b in variants(a):
            if b in byp and b!=a:
                ra,rb=find(a),find(b)
                if ra!=rb: parent[ra]=rb
    g=defaultdict(list)
    for p in pats: g[find(p)]+=byp[p]
    return {k:v for k,v in g.items() if len(v)>1}
