def bbox_overlap(cells, other_cells):
    """True if two cell sets' bounding boxes overlap."""
    r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
    o0 = min(r for r, c in other_cells); o1 = max(r for r, c in other_cells)
    p0 = min(c for r, c in other_cells); p1 = max(c for r, c in other_cells)
    return not (r1 < o0 or r0 > o1 or c1 < p0 or c0 > p1)


